css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;700&display=swap");

*,
::after,
::before {
  -webkit-box-sizing: border-box;
          box-sizing: border-box;
}

html {
  line-height: 1.15;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  color: #666;
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.6em;
  overflow-x: hidden;
  background-color: #fff;
}

table {
  width: 100%;
  caption-side: bottom;
  border-collapse: collapse;
}

th {
  text-align: left;
  padding: 10px 15px;
  line-height: 1.55em;
}

td {
  border-top: 1px solid #dbdfea;
  padding: 10px 15px;
  line-height: 1.55em;
}

.tm_width_1111 { width: 4%; }
.tm_width_333 { width: 20%; }
.tm_width_33 { width: 30%; }
.tm_width_111 { width: 10%; }
.tm_width_3333 { width: 18%; }
.tm_width_3 { width: 25%; }

.tm_gray_bg { background: #f5f6fa; }
.tm_border_left { border-left: 1px solid #dbdfea; }
.tm_round_border2 { border: 1px solid #dbdfea; border-left: 0px; overflow: hidden; border-radius: 6px; }
.tm_round_border { border: 1px solid #dbdfea; overflow: hidden; border-radius: 6px; }

.tm_text_center { text-align: center; }
.tm_text_right { text-align: right; }
.tm_text_left { text-align: left; }
.tm_text_uppercase { text-transform: uppercase; }

.tm_bold { font-weight: 700; }
.tm_semi_bold { font-weight: 600; }
.tm_primary_color { color: #111; }
.td_vertical_align_middle { vertical-align: middle; }

.tm_f50 { font-size: 50px; }
.tm_f20 { font-size: 20px; }
.tm_f16 { font-size: 16px; }

.tm_mb20 { margin-bottom: 20px; }
.tm_mb10 { margin-bottom: 10px; }
.tm_mb30 { margin-bottom: 30px; }
.tm_m0 { margin: 0px; }

.tm_padd_15 { padding: 15px; }
.tm_padd_10 { padding: 10px; }
.tm_padd_5 { padding: 5px; }
.tm_padd_15_20 { padding: 15px 20px; }
.tm_radius_6 { border-radius: 6px !important; }

.tm_invoice_head { display: flex; justify-content: space-between; align-items: center; }
.tm_invoice_footer { display: flex; }
.tm_invoice_footer .tm_left_footer { width: 58%; padding: 10px 15px; }
.tm_invoice_footer .tm_right_footer { width: 42%; }

.tm_border_none { border: none !important; }
.tm_border_top { border-top: 1px solid #dbdfea; }
.tm_border_bottom { border-bottom: 1px solid #dbdfea; }
.tm_invoice_seperator { min-height: 18px; border-radius: 1.6em; flex: 1; margin-right: 20px; }

.tm_logo img { max-height: 50px; }
.tm_sign img { max-height: 150px; }

@media print {
  .tm_gray_bg { background-color: #f5f6fa !important; -webkit-print-color-adjust: exact; }
  .tm_invoice { padding: 10px; }
}
